export async function execMetadata(hostArgs: Record<string, unknown>) {
  {
    const info = hostArgs as Record<string, any>;
    info.user_agent = perlCompat.userAgent();
    for (const c of (info.user_agent_cookies ?? []) as { name: string; value: string; domain: string; path: string }[]) {
      info.user_agent.cookie_jar.add(c);
    }
  }
  // (shift) discarded positional arg — legacy Perl-OOP invocant/first @_ slot
  let lrr_info = hostArgs as Record<string, any>;
  //# Global info hash
  let logger = perlCompat.getLogger("Hentag", "plugins");
  let file = lrr_info["file_path"];
  let path_in_archive = (hostArgs.sidecar_files as Record<string, string> | undefined)?.["info.json"];
  if ((! path_in_archive)) { throw new Error("No hentag info.json file found in this archive!\n"); }
  //    #Extract info.json

  let filepath = path_in_archive;
  //    #Open it

  let stringjson = "";
  let fh = filepath;
  if (fh === undefined) { throw new Error(`Could not open ${filepath}!\n`); }
  for (let row of (fh ?? "").split(/\r?\n/)) {
    row = perlCompat.chomp(row);
    stringjson += row;
  }
  //    #Use Mojo::JSON to decode the string into a hash

  let hashjson = JSON.parse(stringjson);
  logger.debug(`Found and loaded the following JSON: ${stringjson}`);
  //    #Parse it

  let [tags, title] = tags_from_hentag_json(hashjson);
  //    #Delete it

  ;
  //    #Return tags

  logger.info(`Sending the following tags to LRR: ${tags}`);
  if (title) {
    logger.info(`Parsed title is ${title}`);
    return { tags: tags, title: title };
  } else if (tags !== "") {
    return { tags: tags };
  }
}

function tags_from_hentag_json(...args: any[]) {
  let [hash] = args.slice(0);
  let found_tags = [] as any[];
  let title = hash["title"];
  let parodies = hash["parodies"];
  let groups = hash["circles"];
  let artists = hash["artists"];
  let characters = hash["characters"];
  let maleTags = hash["maleTags"];
  let femaleTags = hash["femaleTags"];
  let otherTags = hash["otherTags"];
  let language = language_from_hentag_json(hash);
  let urls = hash["locations"];
  //    # not handled yet: category, createdAt

  //    # tons of different shit creates different kinds of info.json file, so validate the shit out of the data

  found_tags = try_add_tags(found_tags, "series:", parodies);
  found_tags = try_add_tags(found_tags, "group:", groups);
  found_tags = try_add_tags(found_tags, "artist:", artists);
  found_tags = try_add_tags(found_tags, "character:", characters);
  found_tags = try_add_tags(found_tags, "male:", maleTags);
  found_tags = try_add_tags(found_tags, "female:", femaleTags);
  found_tags = try_add_tags(found_tags, "other:", otherTags);
  if (!(! (language !== undefined && language !== null))) { found_tags.push("language:" + language); }
  found_tags = try_add_tags(found_tags, "source:", urls);
  //    #Done-o

  let concat_tags = found_tags.join(", ");
  return [concat_tags, title];
}

function language_from_hentag_json(...args: any[]) {
  let [hash] = args.slice(0);
  let language = hash["language"];
  return language;
}

function try_add_tags(...args: any[]) {
  let found_tags = args[0];
  let prefix = args[1];
  let tags = args[2];
  let potential_tags = [] as any[];
  if (perlCompat.refType(tags) === 'ARRAY') {
    for (let tag of tags) {
      if (perlCompat.refType(tag) === 'HASH' || perlCompat.refType(tag) === 'ARRAY') {
        //                # Weird stuff in here, don't continue parsing to avoid garbage data
      
        return found_tags;
      }
      potential_tags.push(prefix + tag);
    }
  }
  found_tags.push(potential_tags);
  return found_tags;
}
